# PTX source for Swish activation (fp16 input/output)
PTX_SOURCE = r'''
.version 7.0
.target sm_80
.address_size 64

// Constants
.visible .const .f32 LOG2E = 1.4426950408889634;
.visible .const .f32 ONE_F = 1.0;
.visible .const .f32 ONE_F32 = 1.0;

.entry swish_kernel (
    .param .u64 in_ptr,
    .param .u64 out_ptr,
    .param .u32 N
)
{
    // Thread index
    .reg .u32   %tid_x;
    .reg .u32   %block_dim_x;
    .reg .u64   %global_tid;
    .reg .u64   %in, %out;
    .reg .u32   %n;

    ld.param.u64    %in, [in_ptr];
    ld.param.u64    %out, [out_ptr];
    ld.param.u32    %n, [N];

    mov.u32 %tid_x, %tid.x;
    mov.u32 %block_dim_x, %ntid.x;
    cvt.u64.u32 %global_tid, %tid_x;
    mul.lo.u64 %global_tid, %global_tid, %block_dim_x;
    add.u64 %global_tid, %global_tid, %ctaid.x;

    // Loop over elements (grid-stride loop)
    .reg .u64   %idx;
    .reg .b16   %x_half;
    .reg .f32   %x_f, %neg_x_f, %tmp_f, %exp_f, %den_f, %sig_f, %y_f;
    .reg .b16   %y_half;

    mov.u64 %idx, %global_tid;
LOOP:
    setp.ge.u64 %p, %idx, %n;
    @%p bra DONE;

    // Load fp16 element
    ld.global.nc.b16 %x_half, [%in + %idx*2];

    // Convert to fp32
    cvt.f32.b16 %x_f, %x_half;

    // Compute sigmoid: 1 / (1 + exp(-x))
    neg.f32 %neg_x_f, %x_f;
    mul.f32 %tmp_f, %neg_x_f, LOG2E;          // tmp = -x * log2(e)
    ex2.approx.f32 %exp_f, %tmp_f;           // exp(-x) ≈ 2^(tmp)
    add.f32 %den_f, ONE_F, %exp_f;           // 1 + exp(-x)
    rcp.approx.f32 %sig_f, %den_f;           // 1 / (1+exp(-x))

    // y = x * sigmoid
    mul.f32 %y_f, %x_f, %sig_f;

    // Convert back to fp16
    cvt.rn.f16.f32 %y_half, %y_f;

    // Store result
    st.global.nc.b16 [%out + %idx*2], %y_half;

    // idx += gridDim.x * blockDim.x
    add.u64 %idx, %idx, %gridDim.x;
    mul.lo.u64 %tmp_f, %gridDim.x, %block_dim_x;
    add.u64 %idx, %idx, %tmp_f;
    bra LOOP;

DONE:
    ret;
}
'''
# Model wrapper that uses the PTX harness
class ModelNew:
    def __init__(self):
        # Load the PTX module (ptx_harness provides ptx_load)
        self.module = ptx_load(PTX_SOURCE)

    def __call__(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure input is fp16
        if x.dtype != torch.float16:
            raise TypeError("ModelNew expects fp16 inputs")
        out = torch.empty_like(x)

        total_elems = x.numel()
        block = 256
        grid = (total_elems + block - 1) // block

        # Launch kernel: kernel name, grid dim, block dim, arguments list
        ptx_launch(
            self.module,
            "swish_kernel",
            (grid, 1, 1),          # grid dimensions
            (block, 1, 1),         # block dimensions
            [x.data_ptr(), out.data_ptr(), total_elems]  # kernel args
        )
        return out
